/* City Brush v37 · landmark intro cards · Hong Kong (all 93 targets of hk/targets.json, plus site entries)
   Data contract: SC/lm31/BRIEF.md. Labelled keys: k kind, y year, a architect, h height m, fl floors, d description, x extra facts.
   'site:<key>' copies exist for the targets that may be built as SITES (the site key = the target key), and a few
   'site:<key>:<OSM en name>' entries for site building labels. Secondary pieces (<key>_b …) need no entry: the card resolves
   them to their parent by key prefix. Original writing; fields left out where not certain. Generated by build.js. */
Object.assign(window.LM_INFO = window.LM_INFO || {}, {

  /* central */
  hkifc2: {"k":{"zh":"摩天大楼","en":"Skyscraper"},"y":"2003","a":{"zh":"西萨·佩里","en":"César Pelli"},"h":412,"fl":88,"d":{"zh":"国际金融中心二期是港岛最高的建筑，矗立在中环填海区、香港站的正上方。塔身层层收分，顶部以一圈竖向鳍片收束，像一支插向天空的笔。它是维港天际线最醒目的地标之一，也曾出现在多部好莱坞电影里。","en":"Two IFC is the tallest building on Hong Kong Island, standing on the Central reclamation right above Hong Kong Station. The tower steps in as it rises and ends in a crown of vertical fins. It is one of the most familiar shapes of the harbour skyline and has appeared in several Hollywood films."},"x":[{"zh":"与国际金融中心一期、商场和四季酒店组成同一综合体","en":"Part of one complex with One IFC, the mall and a hotel"}]},
  hkifc1: {"k":{"zh":"摩天大楼","en":"Skyscraper"},"y":"1998","a":{"zh":"西萨·佩里","en":"César Pelli"},"h":210,"fl":38,"d":{"zh":"国际金融中心一期是这个综合体里最早落成的塔楼，和旁边的二期出自同一位建筑师，同样是逐级收分的玻璃幕墙造型，只是矮了一半。两座塔楼由国际金融中心商场的裙楼连在一起。","en":"One IFC was the first tower of the International Finance Centre complex. It was designed by the same architect as its taller sister and uses the same stepped glass form, at about half the height. The two towers are joined by the podium of the IFC Mall."}},
  hkifcmall: {"k":{"zh":"商场","en":"Shopping mall"},"d":{"zh":"国际金融中心商场是连接两座国金塔楼与酒店的大型裙楼商场，位于香港站之上。商场顶层有一片对公众开放的屋顶花园，可以俯瞰维港和对岸九龙。机场快线的市区预办登机大厅就在商场下面。","en":"The IFC Mall is the large podium that links the two IFC towers and a hotel, built on top of Hong Kong Station. On its roof is a public garden with views over Victoria Harbour to Kowloon. The Airport Express in-town check-in hall lies below the mall."}},
  hkstation: {"k":{"zh":"铁路车站","en":"Railway station"},"y":"1998","d":{"zh":"香港站是机场快线和东涌线在港岛的总站，深藏在国际金融中心的裙楼下面。旅客可以在这里预办登机、托运行李，再乘车直达机场。车站有地下通道连接中环站，地面上只看得到出入口。","en":"Hong Kong Station is the Hong Kong Island terminus of the Airport Express and the Tung Chung Line, built deep under the IFC podium. Air travellers can check in and drop their bags here before riding to the airport. Underground passages connect it to Central Station."},"x":[{"zh":"设有机场快线市区预办登机服务","en":"Offers Airport Express in-town check-in"}]},
  hkexchange: {"k":{"zh":"办公大楼群","en":"Office towers"},"y":"1985–1988","a":{"zh":"巴马丹拿","en":"P&T Group"},"h":188,"fl":52,"d":{"zh":"交易广场由三座外墙为粉红花岗岩与银色玻璃的办公塔楼组成，一座和二座高188米，三座稍矮。塔楼下面是平台广场和巴士总站，平台上摆放着雕塑作品。香港交易所就设在这里。","en":"Exchange Square is a group of three office towers clad in pink granite and silver glass. One and Two are 188 metres tall, Three is lower. They stand on a podium with a plaza and sculptures, above a bus terminus. The Hong Kong stock exchange is based here."},"x":[{"zh":"一座、二座1985年落成，三座1988年","en":"One and Two finished 1985, Three in 1988"}]},
  hkjardine: {"k":{"zh":"摩天大楼","en":"Skyscraper"},"y":"1972","a":{"zh":"巴马丹拿","en":"Palmer and Turner"},"h":178.5,"fl":52,"d":{"zh":"怡和大厦原名康乐大厦，落成时是香港乃至亚洲最高的建筑。白色铝板外墙上布满约1750个圆形窗户，像轮船的舷窗，让人一眼就能认出。大厦于1989年改用现名。","en":"Jardine House, first called Connaught Centre, was the tallest building in Hong Kong and in Asia when it opened. Its white aluminium facade is covered with about 1,750 round windows that look like portholes on a ship. It took its present name in 1989."}},
  hkcentralpiers: {"k":{"zh":"渡轮码头","en":"Ferry piers"},"y":"1995","d":{"zh":"中环码头是一排沿海港排开的渡轮码头，从这里可以乘船前往长洲、南丫岛、坪洲、梅窝和愉景湾等地。码头在1990年代随中环填海建成，首批于1995年启用。8号码头里还设有香港海事博物馆。","en":"The Central Ferry Piers are a row of piers along the harbour where ferries leave for outlying islands such as Cheung Chau, Lamma, Peng Chau, Mui Wo and Discovery Bay. They were built on the Central reclamation in the 1990s, the first ones opening in 1995. Pier 8 houses the Hong Kong Maritime Museum."},"x":[{"zh":"7号码头是天星小轮往尖沙咀的码头","en":"Pier 7 serves the Star Ferry to Tsim Sha Tsui"}]},
  hkstarferryc: {"k":{"zh":"渡轮码头","en":"Ferry pier"},"y":"2006","d":{"zh":"中环天星码头即中环7号码头，2006年启用，外观仿照爱德华时代风格，设有钟楼。它取代了原本位于爱丁堡广场的旧码头，旧码头的拆除曾引起市民的保育运动。天星小轮从这里横渡维港前往尖沙咀。","en":"The Central Star Ferry Pier, also known as Pier 7, opened in 2006 in an Edwardian-style design with a clock tower. It replaced the old pier at Edinburgh Place, whose demolition led to a public heritage campaign. Star Ferry boats cross Victoria Harbour from here to Tsim Sha Tsui."}},
  hkwheel: {"k":{"zh":"摩天轮","en":"Observation wheel"},"y":"2014","h":60,"d":{"zh":"香港摩天轮位于中环海滨，高约60米，2014年12月开放。轮上有42个封闭式车厢，其中一个是玻璃地板的贵宾车厢。坐一圈可以从高处看到维港两岸的高楼，夜里轮身亮起彩色灯光。","en":"The Hong Kong Observation Wheel stands on the Central harbourfront. It is about 60 metres tall and opened in December 2014. It has 42 enclosed gondolas, one of them a VIP cabin with a glass floor. A ride gives a high view of the towers on both sides of the harbour, and the wheel is lit in colours at night."},"x":[{"zh":"普通车厢最多可坐8人","en":"A standard gondola holds up to eight people"}]},
  hkcentralfront: {"k":{"zh":"海滨长廊","en":"Waterfront promenade"},"d":{"zh":"中环海滨长廊是建在中环填海土地上的一段开放海滨，有草坪、步道和休憩空间，西接中环码头，东面通往添马公园和湾仔。这里经常举办嘉年华、音乐会等户外活动，也是看维港夜景的好地方。","en":"The Central Harbourfront is an open waterfront on reclaimed land, with lawns, walkways and places to sit. It runs from the Central Ferry Piers east towards Tamar Park and Wan Chai. Fairs, concerts and other outdoor events are often held here, and it is a good place to watch the harbour at night."}},

  /* admiralty */
  hkboc: {"k":{"zh":"摩天大楼","en":"Skyscraper"},"y":"1990","a":{"zh":"贝聿铭","en":"I. M. Pei"},"h":367.4,"fl":72,"d":{"zh":"中银大厦由贝聿铭设计，四个三角形玻璃柱体在不同高度依次收顶，构思来自节节高升的竹子。外墙上的白色斜撑既是主要结构，也形成了标志性的菱形图案，夜里由白色灯带勾勒出来。它是美国以外首座超过305米的建筑。","en":"The Bank of China Tower, by I. M. Pei, is made of four triangular glass shafts that stop at different heights, an idea drawn from bamboo growing section by section. The white diagonal bracing is the main structure and forms the famous diamond pattern, outlined by white lights at night. It was the first building outside the United States taller than 305 metres."},"x":[{"zh":"高度含楼顶两根天线","en":"The height includes the two masts"}]},
  hkhsbc: {"k":{"zh":"银行总部大楼","en":"Bank headquarters"},"y":"1985","a":{"zh":"诺曼·福斯特","en":"Norman Foster"},"h":178.8,"d":{"zh":"汇丰总行大厦由诺曼·福斯特设计，没有中央核心筒，楼层由外露的钢桁架像衣架一样挂起，形成三段高低不同的塔身。底层是对公众开放的通道，门前守着两只铜狮，铜狮身上至今留有二战时的弹痕。","en":"The HSBC Main Building, by Norman Foster, has no central core: its floors hang from exposed steel trusses like coat hangers, forming three slabs of different heights. The ground floor is an open public passage guarded by two bronze lions. The lions still carry scars from the Second World War."},"x":[{"zh":"落成时是世界上造价最高的建筑之一","en":"One of the most expensive buildings in the world when finished"}]},
  hkcheungkong: {"k":{"zh":"摩天大楼","en":"Skyscraper"},"y":"1999","a":{"zh":"西萨·佩里","en":"César Pelli"},"h":283,"d":{"zh":"长江集团中心是一座方正的玻璃钢结构塔楼，位于中银大厦和汇丰总行之间。外墙的方格在夜间由灯光点亮，不断变换颜色，是“幻彩咏香江”灯光秀的一部分。塔楼四周设有公众休憩花园。","en":"Cheung Kong Center is a square glass-and-steel tower set between the Bank of China Tower and the HSBC building. At night its facade grid lights up in changing colours as part of the Symphony of Lights show. Public gardens surround the base of the tower."}},
  hklippo: {"k":{"zh":"摩天大楼","en":"Skyscraper"},"y":"1988","a":{"zh":"保罗·鲁道夫","en":"Paul Rudolph"},"h":186,"d":{"zh":"力宝中心由两座八角形塔楼组成，二座高186米，一座稍矮。外墙上一簇簇突出的玻璃盒子，让人联想到树熊抱着树干，因此有“树熊大厦”的外号。它原名奥本大厦，由美国建筑师保罗·鲁道夫设计。","en":"Lippo Centre is a pair of octagonal towers; Tower 2 is 186 metres and Tower 1 a little lower. Clusters of glass boxes stick out from the walls, which reminded people of koalas hugging a tree, so the towers are nicknamed the koala trees. It was first called the Bond Centre and was designed by Paul Rudolph."}},
  hkcfa: {"k":{"zh":"历史建筑","en":"Historic building"},"y":"1912","a":{"zh":"阿斯顿·韦伯、英格雷斯·贝尔","en":"Aston Webb, Ingress Bell"},"d":{"zh":"终审法院大楼是一座新古典主义花岗岩建筑，有中央穹顶和爱奥尼柱廊，三角楣上立着蒙眼的正义女神像。它原是最高法院，1985年至2011年为立法局及立法会所在，2015年起成为终审法院。门前是皇后像广场。","en":"This neoclassical granite building has a central dome, Ionic colonnades and a blindfolded statue of Justice on its pediment. It was built for the Supreme Court, housed the legislature from 1985 to 2011, and has been the Court of Final Appeal since 2015. Statue Square lies in front."},"x":[{"zh":"法定古迹","en":"A declared monument"}]},
  hkbocold: {"k":{"zh":"历史建筑","en":"Historic building"},"y":"1951","a":{"zh":"巴马丹拿","en":"Palmer and Turner"},"d":{"zh":"旧中国银行大厦是一座装饰艺术风格的花岗岩大楼，楼身逐级收窄，紧挨着汇丰总行。建造时有意要比旁边的汇丰旧楼更高。大楼顶部三层自1991年起是一家老上海风格的会所。","en":"The old Bank of China Building is an Art Deco granite tower with stepped massing, standing right next to the HSBC headquarters. It was built with the aim of rising higher than the neighbouring HSBC building of the time. Since 1991 its top three floors have been a club in old Shanghai style."}},
  hkcityhall: {"k":{"zh":"文化场馆","en":"Civic centre"},"y":"1962","a":{"zh":"罗纳德·菲利普斯、艾伦·菲奇","en":"Ron Phillips, Alan Fitch"},"d":{"zh":"香港大会堂是香港第一座公共文化中心，由低座、高座和纪念花园组成，属简洁的现代主义风格。低座有音乐厅和剧院，高座有图书馆和婚姻登记处，纪念花园内的纪念龛用以悼念二战中殉难的人士。","en":"Hong Kong City Hall was the city’s first public cultural centre, a modernist group of a Low Block, a High Block and a memorial garden. The Low Block holds a concert hall and theatre, the High Block a library and a marriage registry. A shrine in the garden honours those who died in the Second World War."}},
  hklegco: {"k":{"zh":"政府建筑","en":"Government building"},"y":"2011","a":{"zh":"许李严建筑师事务所","en":"Rocco Design Architects"},"d":{"zh":"立法会综合大楼位于添马，2011年启用，是立法会会议厅和议员办公室所在。大楼以白色框架和大面积玻璃为主，与旁边的政府总部同属一个设计，一起面向维港和添马公园。","en":"The Legislative Council Complex at Tamar opened in 2011 and holds the council chamber and members’ offices. Its white frames and large glass walls belong to the same design as the government headquarters next door, and both face the harbour and Tamar Park."}},
  hkcgo: {"k":{"zh":"政府建筑","en":"Government building"},"y":"2011","a":{"zh":"许李严建筑师事务所","en":"Rocco Design Architects"},"d":{"zh":"政府总部由东西两座办公楼组成，两座楼在高处相连，中间留出一个巨大的开口，像一扇面向维港的大门，设计理念是“门常开”。大门下方的草坪一路缓缓伸向海边的添马公园。","en":"The Central Government Offices are two office wings joined high up, leaving a huge opening between them like a giant door facing the harbour. The idea behind the design is a door that is always open. A lawn slopes down from under the opening towards Tamar Park and the sea."}},
  hktamar: {"k":{"zh":"公园","en":"Park"},"y":"2011","d":{"zh":"添马公园是政府总部前一片向海边缓缓倾斜的大草坪，市民可以在这里野餐、休息、看海。“添马”一名来自英国皇家海军基地添马舰，基地曾设在这一带的海旁。公园与中环和湾仔的海滨长廊相连。","en":"Tamar Park is a broad lawn that slopes gently from the government headquarters to the water, a place to picnic, rest and watch the harbour. The name comes from HMS Tamar, the Royal Navy base that once stood on this shore. The park links to the harbourfront walks of Central and Wan Chai."}},

  /* midlevels */
  hkthecenter: {"k":{"zh":"摩天大楼","en":"Skyscraper"},"y":"1998","a":{"zh":"刘荣广伍振民建筑师事务所","en":"Dennis Lau & Ng Chun Man"},"h":346,"fl":73,"d":{"zh":"中环中心是一座钢结构摩天楼，顶部层层退台，再接一根尖杆。夜里外墙上一圈圈横向的霓虹灯带不断变换颜色，从维港对岸看格外显眼。它坐落在中环与上环之间的皇后大道中一带。","en":"The Center is a steel-framed skyscraper with a stepped crown topped by a mast. At night rings of horizontal neon bands run up the tower and change colour, easy to spot from across the harbour. It stands between Central and Sheung Wan, near Queen’s Road Central."}},
  hkstjohn: {"k":{"zh":"教堂","en":"Cathedral"},"y":"1849","d":{"zh":"圣约翰座堂是香港历史最悠久的西式教会建筑，属维多利亚哥特式风格，有方形钟楼和尖拱窗。它是香港圣公会的主教座堂，所在土地是香港唯一的永久业权土地。","en":"St John’s Cathedral is the oldest Western church building in Hong Kong, in Victorian Gothic style with a square tower and pointed windows. It is the cathedral of the Anglican Church in Hong Kong. Its land is the only freehold land in Hong Kong."},"x":[{"zh":"法定古迹","en":"A declared monument"}]},
  hkgovhouse: {"k":{"zh":"官邸","en":"Official residence"},"y":"1855","a":{"zh":"查尔斯·克莱弗利","en":"Charles St George Cleverly"},"d":{"zh":"礼宾府建于1855年，曾是历任港督的官邸，回归后成为行政长官官邸。日占时期在原有建筑上加建了一座日式塔楼，屋顶也改成日式风格，形成今天中西混合的外观。每年春天杜鹃花开时会开放给公众参观。","en":"Government House was finished in 1855 and was the home of Hong Kong’s governors; it is now the residence of the Chief Executive. During the Japanese occupation a Japanese-style tower and roofs were added, giving it today’s mixed look. It opens to the public on a spring weekend when the azaleas bloom."}},
  hkflagstaff: {"k":{"zh":"历史建筑","en":"Historic building"},"y":"1846","d":{"zh":"旧三军司令官邸是香港现存最古老的西式建筑，白色外墙配上宽敞的游廊，属希腊复兴风格。它原是驻港英军司令的住所，1984年改为茶具文物馆，坐落在香港公园内。","en":"Flagstaff House is the oldest surviving Western-style building in Hong Kong, a white Greek Revival house with wide verandahs. It was the home of the commander of the British forces. Since 1984 it has been the Museum of Tea Ware, inside Hong Kong Park."},"x":[{"zh":"1984年起为茶具文物馆","en":"Museum of Tea Ware since 1984"}]},
  hktaikwun: {"k":{"zh":"古迹活化项目","en":"Heritage centre"},"y":"2018","a":{"zh":"赫尔佐格和德梅隆（新建部分）","en":"Herzog & de Meuron (new buildings)"},"d":{"zh":"大馆由前中区警署、前中央裁判司署和域多利监狱三组法定古迹组成，共有16座历史建筑围绕着检阅广场。经香港赛马会活化后于2018年开放，新增了两座铝质外墙的现代建筑，用作美术馆和表演场地。","en":"Tai Kwun brings together three declared monuments: the former Central Police Station, the Central Magistracy and Victoria Prison, with 16 historic buildings around a parade ground. Revitalised by the Hong Kong Jockey Club, it opened in 2018 with two new aluminium-clad buildings for art and performances."},"x":[{"zh":"历史建筑建于19世纪中至1919年","en":"Historic blocks date from the mid-1800s to 1919"}]},
  hkmanmo: {"k":{"zh":"庙宇","en":"Temple"},"y":"1847","d":{"zh":"文武庙位于荷李活道，1847年由华人商人兴建，供奉文昌帝君和关圣帝君，也就是“文”与“武”二神。庙内悬挂着许多巨大的盘香，终日香烟缭绕。它是香港最重要的传统庙宇之一，现由东华三院管理。","en":"Man Mo Temple on Hollywood Road was built by Chinese merchants in 1847 for Man, the god of literature, and Mo, the god of war. Huge incense coils hang from the ceiling and fill the halls with smoke. It is one of the most important traditional temples in Hong Kong and is run by the Tung Wah Group."},"x":[{"zh":"法定古迹","en":"A declared monument"}]},
  hkwesternmkt: {"k":{"zh":"历史建筑","en":"Historic building"},"y":"1906","d":{"zh":"西港城原是上环的街市大楼，1906年落成，红砖与白色石材相间，四角设有塔楼，是典型的爱德华时代风格。它是香港现存最古老的街市建筑，如今改作商场，以布匹商店闻名。","en":"Western Market was built as a market hall in Sheung Wan in 1906. Its red and cream brick bands, corner towers and arched windows are typical of the Edwardian style. It is the oldest surviving market building in Hong Kong and now holds shops, known for its cloth sellers."},"x":[{"zh":"法定古迹","en":"A declared monument"}]},
  hkpmq: {"k":{"zh":"创意中心","en":"Creative hub"},"y":"1951","d":{"zh":"元创方原是1951年建成的已婚警察宿舍，两座长条形楼房带外廊，围合出中间的庭院。这里早年是中央书院的校址。经活化后于2014年开放，成为设计师工作室和小店聚集的创意中心。","en":"PMQ was built in 1951 as housing for married police officers: two long blocks with open corridors around a central courtyard. The site was earlier home to the Central School. After revitalisation it reopened in 2014 as a creative hub of design studios and small shops."},"x":[{"zh":"2014年活化开放","en":"Reopened as a creative hub in 2014"}]},
  hkjamia: {"k":{"zh":"清真寺","en":"Mosque"},"y":"1915","d":{"zh":"些利街清真寺是香港最古老的清真寺，最早建于1890年，1915年重建成今天的样子。寺身漆成浅绿和白色，设有宣礼塔和拱形外廊，静静地坐落在中环半山扶手电梯旁的小街里。","en":"Jamia Mosque on Shelley Street is the oldest mosque in Hong Kong. It was first built in 1890 and rebuilt in its present form in 1915. Painted pale green and white, with a minaret and an arched verandah, it sits quietly on a lane beside the Mid-Levels escalator."}},
  hkzoo: {"k":{"zh":"动植物公园","en":"Zoological and botanical garden"},"y":"1871","d":{"zh":"香港动植物公园是香港历史最悠久的公园，建于19世纪60年代，1871年全面落成。园内有喷水池平台、大型鸟舍、哺乳动物园和温室，种着许多热带植物。它依山而建，就在礼宾府的对面。","en":"The Hong Kong Zoological and Botanical Gardens is the oldest park in Hong Kong, begun in the 1860s and completed in 1871. It has a fountain terrace, large aviaries, a mammal section and a greenhouse full of tropical plants. It sits on the hillside across the road from Government House."}},

  /* peak */
  hkpeaktower: {"k":{"zh":"观景建筑","en":"Viewing tower"},"y":"1997","a":{"zh":"泰瑞·法瑞尔","en":"Terry Farrell"},"d":{"zh":"凌霄阁位于太平山顶，由泰瑞·法瑞尔设计，屋顶像一口向上翘起的大镬，下面是石质基座。顶层的摩天台海拔428米，可以俯瞰整个维港。山顶缆车的山顶总站就在楼内。","en":"The Peak Tower, designed by Terry Farrell, stands at the top of the Peak Tram. Its roof is a wide upturned bowl, like a wok, on a stone base. The Sky Terrace on top is 428 metres above sea level and looks over the whole of Victoria Harbour."},"x":[{"zh":"摩天台海拔428米","en":"Sky Terrace 428 m above sea level"}]},
  hkpeakgalleria: {"k":{"zh":"商场","en":"Shopping mall"},"d":{"zh":"山顶广场是凌霄阁旁边的一座阶梯式商场，楼内有商店和餐厅。楼顶设有免费的观景台，可以看到港岛南面的海景，也能远眺维港。它和凌霄阁一起构成太平山顶的游客中心。","en":"The Peak Galleria is a terraced mall next to the Peak Tower, with shops and restaurants inside. Its roof has a free viewing deck facing the south side of Hong Kong Island, with views towards the harbour too. Together with the Peak Tower it forms the visitor centre at the top of the Peak."}},
  hkpeaktram: {"k":{"zh":"登山缆车","en":"Funicular"},"y":"1888","d":{"zh":"山顶缆车1888年通车，是亚洲最早的缆索铁路之一，从中环花园道一路爬上太平山顶。路线大部分是单线，中途有一段让上下行车厢交会的双线，最陡处坡度很大，车窗外的高楼仿佛向后倾斜。","en":"The Peak Tram opened in 1888 and is one of the oldest funicular railways in Asia, climbing from Garden Road in Central to the Peak. Most of the line is a single track with a passing loop halfway. Near the steepest part the towers outside the window seem to lean backwards."},"x":[{"zh":"2022年起使用第六代车厢","en":"Sixth-generation cars since 2022"}]},
  hkpeaktramlower: {"k":{"zh":"缆车站","en":"Funicular station"},"d":{"zh":"山顶缆车花园道总站位于中环花园道旁，紧挨着圣约翰大厦，是缆车的起点站。乘客从这里上车，沿陡峭的山坡一路爬升到太平山顶。车站经过扩建，候车空间更宽敞。","en":"The Garden Road terminus is the lower end of the Peak Tram, next to St John’s Building on Garden Road in Central. Passengers board here for the steep climb up the hillside to the Peak. The station has been enlarged with a bigger waiting area."}},
  hkhku: {"k":{"zh":"大学","en":"University"},"y":"1911","d":{"zh":"香港大学是香港历史最悠久的大学，1911年创立，校园沿薄扶林道的山坡层层分布。红砖与花岗岩建成的本部大楼有钟楼和爱奥尼柱廊，是校园的象征；山坡上方是2012年启用的百周年校园。孙中山曾在其前身香港西医书院求学。","en":"The University of Hong Kong, founded in 1911, is the oldest university in Hong Kong, spread over terraces on the hillside along Pok Fu Lam Road. Its red-brick and granite Main Building with a clock tower is the symbol of the campus, and the Centennial Campus opened above it in 2012. Sun Yat-sen studied at the medical college that came before it."}},
  hkoceanpark: {"k":{"zh":"主题公园","en":"Theme park"},"y":"1977","d":{"zh":"海洋公园1977年开幕，建在港岛南区南朗山的两边：一边是海滨区，另一边是山上的高峰区，两区之间靠架空缆车和地下列车相连。坐缆车可以俯瞰南面开阔的海景，园内还有海洋生物展馆和机动游戏。","en":"Ocean Park opened in 1977 on both sides of a headland on the south side of Hong Kong Island. The Waterfront area and the Summit area are linked by a cable car and an underground train. The cable car gives wide views of the sea, and the park has marine animal exhibits and rides."}},
  hkmurray: {"k":{"zh":"历史建筑","en":"Historic building"},"y":"1846","a":{"zh":"皇家工兵","en":"Royal Engineers"},"d":{"zh":"美利楼1846年建于中环，原是英军军官宿舍。1982年为兴建中银大厦而拆卸，三千多块石构件被逐一编号保存，后来在赤柱海边重新组装，2002年重新开放。三层花岗岩柱廊面向海湾，如今楼内是餐厅。","en":"Murray House was built in Central in 1846 as officers’ quarters for the British army. It was taken down in 1982 to make way for the Bank of China Tower, its more than 3,000 pieces numbered and stored. It was put back together on the shore at Stanley and reopened in 2002. Its three floors of granite colonnades face the bay."}},

  /* wanchai */
  hkcentralplaza: {"k":{"zh":"摩天大楼","en":"Skyscraper"},"y":"1992","a":{"zh":"刘荣广伍振民建筑师事务所","en":"Dennis Lau & Ng Chun Man"},"h":374,"fl":78,"d":{"zh":"中环广场是一座三角形平面的摩天楼，外墙是金色和银色的玻璃，顶部是金字塔形的塔冠和尖杆。落成时是亚洲最高的建筑。塔顶的霓虹灯带每15分钟变换一次颜色，可以用来报时。","en":"Central Plaza is a triangular skyscraper in gold and silver glass, with a pyramid top and a mast. When it was finished it was the tallest building in Asia. The neon bands at the top change colour every 15 minutes, so they can be read like a clock."},"x":[{"zh":"位于湾仔，虽然名字叫“中环”","en":"It stands in Wan Chai despite its name"}]},
  hkcec: {"k":{"zh":"会展中心","en":"Convention centre"},"y":"1997","a":{"zh":"SOM建筑设计事务所（扩建）","en":"Skidmore, Owings & Merrill (extension)"},"d":{"zh":"香港会议展览中心的扩建部分建在维港一个人工岛上，弧形的铝质屋顶像展翅的海鸟，四面是玻璃幕墙。1997年7月1日香港回归的交接仪式就在这里举行。原有的会展中心于1988年启用。","en":"The extension of the Hong Kong Convention and Exhibition Centre stands on an artificial island in the harbour. Its curved aluminium roof looks like a bird spreading its wings, above walls of glass. The handover ceremony of Hong Kong took place here on 1 July 1997. The first part of the centre opened in 1988."}},
  hkbauhinia: {"k":{"zh":"纪念广场","en":"Memorial square"},"y":"1997","d":{"zh":"金紫荆广场位于会展中心旁的海边，中央是一座镀金的紫荆花雕塑，名为“永远盛开的紫荆花”，是中央政府为庆祝香港回归而赠送的。每天早上广场上都会举行升旗仪式，是游客常到的打卡点。","en":"Golden Bauhinia Square is on the waterfront beside the Convention Centre. In its centre stands a gilded bauhinia flower sculpture, a gift from the Central Government to mark the return of Hong Kong in 1997. A flag-raising ceremony is held here every morning."}},
  hkhopewell: {"k":{"zh":"摩天大楼","en":"Skyscraper"},"y":"1980","h":216,"fl":64,"d":{"zh":"合和中心是湾仔山坡上的一座圆柱形摩天楼，1980年落成时是香港最高的建筑。楼顶设有旋转餐厅，外墙装有观景电梯，乘客可以一边上升一边看海港景色。","en":"Hopewell Centre is a round skyscraper on the Wan Chai hillside. When it was finished in 1980 it was the tallest building in Hong Kong. A revolving restaurant sits near the top, and glass lifts on the outside give riders a view of the harbour as they climb."}},
  hkhappyvalley: {"k":{"zh":"赛马场","en":"Racecourse"},"y":"1846","d":{"zh":"跑马地马场坐落在港岛四面环山的谷地里，自1846年起举办赛马，是香港最早的马场。看台沿着跑道排开，周围高楼林立，夜赛时灯火通明。跑道中间的草地平日用作公众运动场。","en":"Happy Valley Racecourse sits in a valley surrounded by hills and towers on Hong Kong Island. Horse races have been held here since 1846, making it the oldest racecourse in Hong Kong. Night races are run under bright floodlights, and the infield is used as public sports pitches."},"x":[{"zh":"常在星期三晚上举行夜赛","en":"Night races are usually held on Wednesdays"}]},
  hkstadium: {"k":{"zh":"体育场","en":"Stadium"},"y":"1994","d":{"zh":"香港大球场位于扫杆埔，1994年重建落成，可容纳约四万名观众。两边看台上方各有一道白色的拱形钢结构支撑顶棚。多年来这里是香港国际七人橄榄球赛的主场，直到赛事于2025年移师启德。","en":"Hong Kong Stadium in So Kon Po was rebuilt in 1994 and holds about 40,000 people. White steel arches carry the roofs over its two long stands. For many years it was the home of the Hong Kong Sevens rugby tournament, until the event moved to Kai Tak in 2025."}},
  hkvicpark: {"k":{"zh":"公园","en":"Park"},"y":"1957","d":{"zh":"维多利亚公园位于铜锣湾，1957年开放，建在填平的避风塘上，是港岛最大的公园之一。园内有维多利亚女王铜像、网球场和游泳池。每逢农历新年的年宵花市和中秋节的灯会都在这里举行。","en":"Victoria Park in Causeway Bay opened in 1957 on a filled-in typhoon shelter and is one of the largest parks on Hong Kong Island. It has a statue of Queen Victoria, tennis courts and a swimming pool. The Lunar New Year flower fair and the Mid-Autumn lantern show are held here each year."}},
  hkoneislandeast: {"k":{"zh":"摩天大楼","en":"Skyscraper"},"y":"2008","a":{"zh":"王欧阳建筑师事务所","en":"Wong & Ouyang"},"h":298.4,"d":{"zh":"港岛东中心位于鲗鱼涌的太古坊，是港岛东部最高的建筑。塔楼平面接近方形，四角切成斜面，外墙是浅色玻璃，塔顶在夜间亮起灯光。它让太古坊从旧工业区变成了大型办公区。","en":"One Island East stands at Taikoo Place in Quarry Bay and is the tallest building in the east of Hong Kong Island. The square tower has cut-off glass corners, and its crown is lit at night. It helped turn Taikoo Place from an old industrial area into a large office district."}},

  /* tst */
  hkclocktower: {"k":{"zh":"钟楼","en":"Clock tower"},"y":"1915","h":44,"d":{"zh":"尖沙咀钟楼是旧九广铁路尖沙咀总站仅存的部分，红砖与花岗岩砌成，顶部有小圆顶和避雷针。车站在1970年代末迁往红磡后被拆除，只留下这座钟楼，见证了乘火车往来九龙与广州的年代。","en":"The Tsim Sha Tsui Clock Tower is all that remains of the old Kowloon–Canton Railway terminus. It is built of red brick and granite, with a small cupola and a lightning rod on top. When the station moved to Hung Hom in the late 1970s the rest was pulled down, and only the tower was kept."},"x":[{"zh":"法定古迹","en":"A declared monument"}]},
  hkculturalcentre: {"k":{"zh":"演艺中心","en":"Performing arts centre"},"y":"1989","a":{"zh":"建筑署","en":"Architectural Services Department"},"d":{"zh":"香港文化中心建在旧火车站的原址上，有音乐厅、大剧院和剧场。建筑外墙铺着粉红色瓷砖，几乎没有窗户，屋顶呈一道向海边倾斜的大弧线。它因为面对维港美景却不开窗而曾引起争议。","en":"The Hong Kong Cultural Centre stands on the site of the old railway station and holds a concert hall, a grand theatre and a studio theatre. Its walls are covered in pink tiles and have almost no windows, and its roof sweeps down towards the sea in a great curve. The lack of windows facing the harbour view was much debated."}},
  hkspacemuseum: {"k":{"zh":"天文馆","en":"Planetarium"},"y":"1980","a":{"zh":"建筑署","en":"Architectural Services Department"},"d":{"zh":"香港太空馆位于尖沙咀海旁，白色的半蛋形穹顶是它最明显的特征，穹顶下面是天象厅，可以放映天象节目和球幕电影。它是香港首座天文馆，紧邻文化中心和艺术馆。","en":"The Hong Kong Space Museum on the Tsim Sha Tsui waterfront is known for its white, half-egg-shaped dome. Under the dome is a planetarium theatre that shows sky shows and dome films. It was the first planetarium in Hong Kong and stands next to the Cultural Centre and the Museum of Art."}},
  hkmuseumart: {"k":{"zh":"博物馆","en":"Museum"},"y":"1991","d":{"zh":"香港艺术馆1962年创立，1991年迁到尖沙咀海旁现址。经过数年翻新，2019年重新开放，加建了玻璃外墙的顶层，展厅可以直接看到维港。馆藏以中国书画、古代文物和香港艺术为主。","en":"The Hong Kong Museum of Art was founded in 1962 and moved to this site on the Tsim Sha Tsui waterfront in 1991. After several years of renovation it reopened in 2019 with a new glazed top floor whose galleries look out over the harbour. Its collection focuses on Chinese painting, antiquities and Hong Kong art."}},
  hkavenuestars: {"k":{"zh":"海滨长廊","en":"Waterfront promenade"},"y":"2004","d":{"zh":"星光大道是尖沙咀东部的海滨长廊，2004年开放，用以表扬香港电影人，沿途有明星手印和李小龙铜像。2019年重新设计开放，加建了波浪形的遮荫顶篷。这里是隔海欣赏港岛天际线的经典位置。","en":"The Avenue of Stars is a waterfront promenade in Tsim Sha Tsui East, opened in 2004 to honour Hong Kong’s film industry, with stars’ handprints and a statue of Bruce Lee. It reopened in 2019 with a new design and wavy shade canopies. It is the classic place to view the Hong Kong Island skyline across the water."}},
  hkstarferrytst: {"k":{"zh":"渡轮码头","en":"Ferry pier"},"d":{"zh":"尖沙咀天星码头是天星小轮在九龙的码头，绿白相间的船只从这里开往中环和湾仔。横渡维港只需几分钟，票价便宜，是欣赏两岸景色最经典的方式之一。码头旁就是尖沙咀钟楼。","en":"The Tsim Sha Tsui Star Ferry Pier is the Kowloon end of the Star Ferry, whose green and white boats sail from here to Central and Wan Chai. The crossing takes only a few minutes and costs little, and it is one of the classic ways to see both sides of the harbour. The Clock Tower stands beside the pier."}},
  hkoceanterminal: {"k":{"zh":"邮轮码头","en":"Cruise terminal"},"y":"1966","d":{"zh":"海运大厦1966年启用，是伸入维港的长条形邮轮码头，楼内设有商场，是香港最早的大型商场之一。2017年码头末端加建了福斯特建筑事务所设计的扩建部分，阶梯状的草坪观景台可以三面看海。","en":"Ocean Terminal opened in 1966 as a long cruise pier reaching into the harbour, with shops inside, one of Hong Kong’s first large shopping centres. In 2017 an extension designed by Foster + Partners was added at its tip. Its stepped lawn viewing deck looks out over the water on three sides."}},
  hkpeninsula: {"k":{"zh":"酒店","en":"Hotel"},"y":"1928","d":{"zh":"香港半岛酒店1928年开业，是香港历史最悠久的酒店，H形的新古典主义主楼前有喷水池庭院。1994年在后方加建了一座设有直升机坪的塔楼。1941年圣诞节，港督就是在这里向日军投降。","en":"The Peninsula opened in 1928 and is the oldest hotel in Hong Kong. Its H-shaped neoclassical main block faces a forecourt with a fountain, and a tower with a rooftop helipad was added behind it in 1994. On Christmas Day 1941 the governor of Hong Kong surrendered to the Japanese army here."}},
  hk1881: {"k":{"zh":"历史建筑","en":"Historic building"},"y":"1884","d":{"zh":"1881公馆的前身是建于1884年的前水警总部，建在一座小山岗上，有带外廊的主楼、圆形的时间球塔和马厩。时间球塔曾通过落下圆球向港内船只报时。1996年水警迁出后，这里活化成酒店和商场。","en":"1881 Heritage was the Marine Police Headquarters, built in 1884 on a small hill: a main building with verandahs, a round time-ball tower and stables. A ball dropped from the tower gave ships in the harbour the exact time. After the police left in 1996 the site was turned into a hotel and shops."},"x":[{"zh":"法定古迹","en":"A declared monument"}]},
  hkcoliseum: {"k":{"zh":"室内体育馆","en":"Indoor arena"},"y":"1983","d":{"zh":"香港体育馆俗称“红馆”，1983年启用，建在红磡站上盖的平台上。场馆是一个倒金字塔形的结构，由四根巨大的支柱撑起，可以容纳约一万二千人。这里是香港最著名的演唱会场地。","en":"The Hong Kong Coliseum, known as the Red Hall, opened in 1983 on the podium above Hung Hom Station. The building is an upside-down pyramid held up by four huge legs and seats about 12,500 people. It is Hong Kong’s best-known concert venue."}},

  /* westkowloon */
  hkicc: {"k":{"zh":"摩天大楼","en":"Skyscraper"},"y":"2010","a":{"zh":"KPF建筑师事务所","en":"Kohn Pedersen Fox"},"h":484,"fl":108,"d":{"zh":"环球贸易广场是香港最高的建筑，建在西九龙的九龙站上盖。方形塔身的四角向内凹进，越往上越略为收窄。第100层是天际100观景台，顶部是酒店。夜里外墙变成一面巨大的LED灯幕，参与维港的灯光表演。","en":"The International Commerce Centre is the tallest building in Hong Kong, rising above Kowloon Station in West Kowloon. Its square shaft has notched corners and narrows slightly towards the top. The 100th floor holds the sky100 observation deck and a hotel occupies the top. At night the facade becomes a giant LED screen in the harbour light show."},"x":[{"zh":"天际100观景台位于第100层","en":"sky100 observation deck on floor 100"}]},
  hkmplus: {"k":{"zh":"博物馆","en":"Museum"},"y":"2021","a":{"zh":"赫尔佐格和德梅隆","en":"Herzog & de Meuron"},"d":{"zh":"M+是西九文化区的视觉文化博物馆，2021年开放，收藏20至21世纪的设计、建筑、影像与视觉艺术。建筑由一个水平的基座和一块竖立的薄板组成，朝向维港的立面是一块巨大的LED屏幕，外墙覆有绿色陶瓷百叶。","en":"M+ is the museum of visual culture in the West Kowloon Cultural District, opened in 2021. It collects design, architecture, moving image and visual art of the 20th and 21st centuries. The building is a long low podium with a thin upright slab, whose harbour face is a huge LED screen, clad in green ceramic louvres."}},
  hkxiqu: {"k":{"zh":"戏曲中心","en":"Opera theatre"},"y":"2019","a":{"zh":"谭秉荣建筑事务所、吕元祥建筑师事务所","en":"Revery Architecture, Ronald Lu & Partners"},"d":{"zh":"戏曲中心是专门上演粤剧等中国戏曲的剧院，位于西九文化区东端。外墙由起伏的铝质鳍片组成，整体像一盏传统灯笼，入口处的外墙像舞台帷幕一样被拉开。大剧院可容纳一千多名观众。","en":"The Xiqu Centre is a theatre for Cantonese opera and other forms of Chinese opera, at the eastern end of the West Kowloon Cultural District. Its walls are made of wavy aluminium fins so that the building looks like a traditional lantern. At the entrance the facade opens like a pair of stage curtains."}},
  hkpalacemuseum: {"k":{"zh":"博物馆","en":"Museum"},"y":"2022","a":{"zh":"许李严建筑师事务所","en":"Rocco Design Architects"},"d":{"zh":"香港故宫文化博物馆2022年开放，展出来自北京故宫博物院的珍贵文物。建筑底窄顶宽，层层叠起，造型取意于中国古代青铜器，外墙是金色的铝板，中间一道竖向开口让光线进入中庭。","en":"The Hong Kong Palace Museum opened in 2022 and shows treasures lent by the Palace Museum in Beijing. The building is narrow at the base and wider at the top, a stacked form inspired by ancient Chinese bronze vessels. Its walls are gold-coloured panels, with a tall cut in the middle letting light into the atrium."}},
  hkwkstation: {"k":{"zh":"高铁站","en":"High-speed rail station"},"y":"2018","a":{"zh":"凯达环球（安德鲁·布朗伯格）","en":"Aedas (Andrew Bromberg)"},"d":{"zh":"香港西九龙站是广深港高速铁路的香港总站，2018年启用，大部分月台位于地下。玻璃和钢的巨大屋顶像波浪一样升起，在面向维港的一端形成一扇高大的拱窗。屋顶上有绿化步道，市民可以走上去观景。","en":"Hong Kong West Kowloon Station is the terminus of the high-speed railway to Guangzhou and Shenzhen, opened in 2018, with most platforms underground. Its huge roof of glass and steel rises like a wave to a tall arched window facing the harbour. The roof is planted with gardens and walkways that the public can climb."},"x":[{"zh":"站内设有内地口岸区","en":"The station includes a Mainland port area"}]},
  hkkowloonstation: {"k":{"zh":"铁路车站","en":"Railway station"},"y":"1998","a":{"zh":"泰瑞·法瑞尔事务所","en":"Terry Farrell and Partners"},"d":{"zh":"九龙站是机场快线和东涌线的车站，1998年随新机场一起启用。车站上盖是一个巨大的平台，平台上建有环球贸易广场和多座住宅、酒店塔楼，形成一座“车站上的城市”。旅客也可以在这里预办登机。","en":"Kowloon Station serves the Airport Express and the Tung Chung Line and opened with the new airport in 1998. Above it is a huge podium carrying the International Commerce Centre and many residential and hotel towers, a city built on top of a station. Air travellers can check in here too."}},

  /* kowlooneast */
  hkkaitakcruise: {"k":{"zh":"邮轮码头","en":"Cruise terminal"},"y":"2013","a":{"zh":"福斯特建筑事务所","en":"Foster + Partners"},"h":30,"d":{"zh":"启德邮轮码头建在旧启德机场跑道的末端，2013年启用，可同时停泊两艘大型邮轮。大楼长条形的屋顶像波浪一样起伏，屋顶上是一座公园，可以看到鲤鱼门和维港东部的景色。","en":"Kai Tak Cruise Terminal stands at the tip of the old Kai Tak airport runway and opened in 2013. It can berth two large cruise ships at the same time. The long building has a wave-like roof with a park on top, looking out to Lei Yue Mun and the eastern harbour."}},
  hkkaitakstadium: {"k":{"zh":"体育场","en":"Stadium"},"y":"2025","a":{"zh":"Populous","en":"Populous"},"d":{"zh":"启德主场馆是启德体育园的核心，2025年3月开幕，可容纳五万名观众，是香港最大的体育场。它设有可开合的屋顶，草地可以更换，既能举办足球和橄榄球比赛，也能举办大型演唱会。","en":"Kai Tak Stadium is the centre of the Kai Tak Sports Park and opened in March 2025. It holds 50,000 people, making it the largest stadium in Hong Kong. It has a retractable roof and a pitch that can be changed, so it hosts football and rugby as well as big concerts."},"x":[{"zh":"体育园内还有室内体育馆和公众运动场","en":"The park also has an indoor arena and a public sports ground"}]},
  hkwongtaisin: {"k":{"zh":"道教庙宇","en":"Taoist temple"},"y":"1921","d":{"zh":"黄大仙祠由啬色园管理，1921年在现址建成，主要供奉黄大仙，同时融合儒、释、道三教。红柱金瓦的大殿背靠狮子山，园内有九龙壁和园林。这里以求签灵验著称，农历新年时上头炷香的人潮络绎不绝。","en":"Wong Tai Sin Temple, run by Sik Sik Yuen, was built on this site in 1921 for the deity Wong Tai Sin and brings together Taoism, Buddhism and Confucianism. Its red columns and golden roofs stand with Lion Rock behind. It is famous for fortune sticks, and crowds come to offer the first incense of the Lunar New Year."}},
  hkchilin: {"k":{"zh":"佛寺","en":"Buddhist nunnery"},"y":"1998","d":{"zh":"志莲净苑创建于1934年，1998年按唐代建筑风格重建。殿堂全部以木构件榫卯相接，不用一根铁钉，灰瓦屋顶舒展，围绕着莲花池错落排列。它是香港唯一一组这种风格的仿唐木构建筑群。","en":"Chi Lin Nunnery was founded in 1934 and rebuilt in 1998 in the style of the Tang dynasty. Its halls are made of timber pieces joined without a single nail, with wide grey-tiled roofs set around lotus ponds. It is the only complex in this style in Hong Kong."},"x":[{"zh":"共有16座殿堂","en":"Has 16 halls"}]},
  hknanlian: {"k":{"zh":"园林","en":"Garden"},"y":"2006","d":{"zh":"南莲园池位于志莲净苑对面，2006年开放，由志莲净苑管理，按唐代园林风格建造。园中最引人注目的是一座金色的圆满阁，立在红色木桥旁的池水中央。园内还有奇石、松树和水车屋。","en":"Nan Lian Garden lies across the road from Chi Lin Nunnery, which looks after it. It opened in 2006 and follows the style of Tang dynasty gardens. Its most striking sight is the golden Pavilion of Absolute Perfection standing in a pond beside a red wooden bridge. The garden also has rocks, pines and a water mill."}},
  hklionrock: {"k":{"zh":"山峰","en":"Hill"},"d":{"zh":"狮子山是九龙北面的一座花岗岩山峰，山顶的岩石从侧面看像一头面向西方伏着的狮子。它因电视剧《狮子山下》及其主题曲而成为香港人同舟共济、拼搏向上精神的象征。山下有狮子山隧道穿过。","en":"Lion Rock is a granite hill north of Kowloon whose summit rocks look like a lion crouching and facing west. Through the television series Below the Lion Rock and its theme song it became a symbol of Hong Kong people working hard together. The Lion Rock Tunnel runs beneath it."},"x":[{"zh":"海拔约495米","en":"About 495 m above sea level"}]},
  hkwalledcity: {"k":{"zh":"公园","en":"Park"},"y":"1995","d":{"zh":"九龙寨城公园建在已拆卸的九龙寨城原址上，1995年开放，采用江南园林的风格。寨城曾是世界上人口最稠密的地方之一，拆卸时保留了清代衙门建筑和南门遗迹，如今在园中展示寨城的历史。","en":"Kowloon Walled City Park was built on the site of the demolished Walled City and opened in 1995, in the style of a Jiangnan garden. The Walled City was once one of the most densely populated places on earth. Its Qing dynasty yamen building and the remains of the South Gate were kept and now tell its story."}},
  hkpolyu: {"k":{"zh":"大学","en":"University"},"y":"1937","d":{"zh":"香港理工大学的前身是1937年成立的官立高级工业学院，1994年升格为大学。校园位于红磡，一栋栋红砖教学楼由平台和天桥紧密相连。东北角是扎哈·哈迪德设计的赛马会创新楼，流线形的外观和红砖校舍形成鲜明对比。","en":"The Hong Kong Polytechnic University grew from a government trade school founded in 1937 and became a university in 1994. Its campus in Hung Hom is a dense group of red-brick blocks linked by podiums and bridges. At its north-east corner the flowing Jockey Club Innovation Tower by Zaha Hadid stands out against the brick."}},
  hkust: {"k":{"zh":"大学","en":"University"},"y":"1991","d":{"zh":"香港科技大学1991年创校，位于西贡清水湾的山坡上，校园从山顶一级级伸向海边，可以俯瞰牛尾海。大楼正门前有一座红色的日晷雕塑，学生称它为“红鸟”。它以科学、工程和商科闻名。","en":"The Hong Kong University of Science and Technology opened in 1991 on a hillside at Clear Water Bay, its campus stepping down from the hilltop to the sea. A red sundial sculpture, nicknamed the Red Bird by students, stands in front of the main entrance. The university is known for science, engineering and business."}},
  hkcuhk: {"k":{"zh":"大学","en":"University"},"y":"1963","d":{"zh":"香港中文大学1963年成立，校园在沙田马料水的山坡上，面向吐露港，是香港面积最大的大学校园。它实行书院制，各书院分布在不同的山头。校园中心是大学广场和未圆湖一带。","en":"The Chinese University of Hong Kong was founded in 1963. Its campus at Ma Liu Shui in Sha Tin climbs a hillside above Tolo Harbour and is the largest university campus in Hong Kong. It has a college system, with colleges spread over different hilltops. The University Mall is at the heart of the campus."},"x":[{"zh":"设有九所书院","en":"Has nine colleges"}]},

  /* bridges */
  hktsingma: {"k":{"zh":"悬索桥","en":"Suspension bridge"},"y":"1997","a":{"zh":"莫特麦克唐纳","en":"Mott MacDonald"},"h":206,"d":{"zh":"青马大桥连接青衣岛和马湾，主跨1377米，是通往机场的青屿干线的一部分。它是双层桥：上层是六线行车道，下层是机场快线和东涌线的铁路以及两条在台风时使用的车道。它曾是世界上主跨最长的公路铁路两用悬索桥。","en":"Tsing Ma Bridge links Tsing Yi and Ma Wan with a main span of 1,377 metres, part of the Lantau Link to the airport. It has two decks: six traffic lanes on top, and inside the truss the Airport Express and Tung Chung Line tracks plus two lanes used in typhoons. It was once the longest span of any bridge carrying both road and rail."},"x":[{"zh":"主跨1377米","en":"Main span 1,377 m"}]},
  hkkapshuimun: {"k":{"zh":"斜拉桥","en":"Cable-stayed bridge"},"y":"1997","d":{"zh":"汲水门大桥连接马湾和大屿山，主跨430米，和青马大桥一起组成青屿干线。它是双层斜拉桥，上层走汽车，下层是铁路和台风时使用的车道，两座H形的混凝土桥塔拉起扇形的斜拉索。","en":"Kap Shui Mun Bridge links Ma Wan and Lantau with a main span of 430 metres, and with Tsing Ma Bridge forms the Lantau Link. It is a double-deck cable-stayed bridge, with road traffic on top and the railway and typhoon lanes below. Its two H-shaped concrete towers hold fans of stay cables."},"x":[{"zh":"主跨430米","en":"Main span 430 m"}]},
  hktingkau: {"k":{"zh":"斜拉桥","en":"Cable-stayed bridge"},"y":"1998","a":{"zh":"施莱希·贝格曼","en":"Schlaich Bergermann"},"h":201.55,"d":{"zh":"汀九桥横跨蓝巴勒海峡，连接青衣和新界西部，是世界上较早采用三塔设计的斜拉桥之一。三座纤细的单柱桥塔靠横向和纵向的稳定索保持平衡，两条桥面分开并排在桥塔两侧。","en":"Ting Kau Bridge crosses Rambler Channel between Tsing Yi and the western New Territories. It was one of the first large cable-stayed bridges with three towers. Its slender single-leg towers are steadied by sideways and lengthwise stabilising cables, and the two decks run side by side."},"x":[{"zh":"两个主跨分别为448米和475米","en":"Main spans of 448 m and 475 m"}]},
  hkstonecutters: {"k":{"zh":"斜拉桥","en":"Cable-stayed bridge"},"y":"2009","h":293.5,"d":{"zh":"昂船洲大桥横跨蓝巴勒海峡入口，连接青衣和昂船洲，主跨1018米，2009年通车时是世界上主跨第二长的斜拉桥。两座独柱桥塔下部是混凝土，上部包着不锈钢外壳，桥面是两条分开的流线形箱梁。","en":"Stonecutters Bridge spans the entrance of Rambler Channel between Tsing Yi and Stonecutters Island. Its main span of 1,018 metres made it the second-longest cable-stayed span in the world when it opened in 2009. Its two single towers are concrete below and clad in stainless steel above, and the deck is a pair of streamlined boxes."},"x":[{"zh":"主跨1018米","en":"Main span 1,018 m"}]},
  hkhzmblink: {"k":{"zh":"跨海大桥","en":"Sea bridge"},"y":"2018","d":{"zh":"港珠澳大桥香港连接路从大屿山机场附近的口岸人工岛出发，以长长的高架桥越过海面，连接到大桥主体。港珠澳大桥2018年通车，把香港与珠海、澳门连在一起。连接路上有三段较高的通航孔，供船只通过。","en":"The Hong Kong Link Road of the Hong Kong–Zhuhai–Macao Bridge runs on a long viaduct over the sea from the boundary crossing island near the airport to the main bridge. The bridge opened in 2018 and connects Hong Kong with Zhuhai and Macao. Three higher spans along the link road let ships pass beneath."}},
  hkninatower: {"k":{"zh":"摩天大楼","en":"Skyscraper"},"y":"2007","h":318,"fl":80,"d":{"zh":"如心广场是荃湾的地标，也是新界最高的建筑，以华懋集团已故主席龚如心的名字命名。它由两座高低不同的塔楼连成一体，楼内有酒店和写字楼，顶部是一个骨架般的玻璃塔冠。大楼原计划建得更高，后来因航空高度限制而降低。","en":"Nina Tower is the landmark of Tsuen Wan and the tallest building in the New Territories, named after Nina Wang of the Chinachem Group. Two towers of different heights are joined into one, holding a hotel and offices, with a skeletal glass crown on top. It was first planned to be much taller but was cut back because of aviation height limits."}},

  /* lantau */
  hkt1: {"k":{"zh":"航站楼","en":"Airport terminal"},"y":"1998","a":{"zh":"福斯特建筑事务所","en":"Foster + Partners"},"d":{"zh":"香港国际机场一号客运大楼1998年启用，建在大屿山以北填海而成的赤鱲角上，取代了市区的旧启德机场。大楼呈Y形，屋顶由一排排轻盈的钢拱组成，自然光从拱间洒入。它曾是世界上最大的室内空间之一。","en":"Terminal 1 of Hong Kong International Airport opened in 1998 on Chek Lap Kok, an island enlarged by reclamation north of Lantau, replacing the old Kai Tak airport in the city. The Y-shaped building is covered by rows of light steel vaults that let daylight in between them. It was once one of the largest enclosed spaces in the world."}},
  hkt2: {"k":{"zh":"航站楼","en":"Airport terminal"},"y":"2026","d":{"zh":"二号客运大楼原于2007年启用，2019年起为配合三跑道系统而重建扩建。新大楼的离港设施于2026年5月启用，弧形的大屋顶覆盖着宽阔的离港大厅，设有约160个值机柜台。到港设施预计稍后启用。","en":"Terminal 2 first opened in 2007 and from 2019 was rebuilt and enlarged for the airport’s three-runway system. The departures facilities of the new terminal opened in May 2026, under a large curved roof over a wide departure hall with about 160 check-in counters. Arrivals are due to follow later."}},
  hkmidfield: {"k":{"zh":"客运廊","en":"Concourse"},"y":"2016","d":{"zh":"中场客运廊位于机场两条跑道之间，是一号客运大楼的卫星客运廊，平面呈Y形，2016年启用。旅客从一号客运大楼乘地下的旅客捷运系统前往这里登机，大楼两侧排列着许多停机位。","en":"The Midfield Concourse stands between the airport’s runways as a satellite of Terminal 1. Its plan is Y-shaped and it opened in 2016. Passengers reach it from Terminal 1 by the underground automated people mover, and many aircraft stands line its sides."}},
  hkskypier: {"k":{"zh":"渡轮码头","en":"Ferry terminal"},"y":"2010","a":{"zh":"凯达环球","en":"Aedas"},"d":{"zh":"海天客运码头位于机场岛东部，是机场内的跨境渡轮码头。乘飞机转机的旅客可以从这里直接乘船往返珠江三角洲各港口和澳门，无需办理香港的出入境手续。码头与客运大楼之间有捷运系统连接。","en":"SkyPier is the cross-border ferry terminal inside the airport, at the east end of the airport island. Transfer passengers can sail between the airport and ports in the Pearl River Delta or Macao without passing Hong Kong immigration. An automated people mover links it with the passenger terminals."}},
  hkatc: {"k":{"zh":"控制塔","en":"Control tower"},"d":{"zh":"航空交通控制塔位于一号客运大楼西侧，顶部是四面玻璃的控制室，管制员可以从这里看清跑道和滑行道上的飞机。香港国际机场是世界上最繁忙的机场之一，空中交通由民航处负责管理。","en":"The air traffic control tower stands west of Terminal 1, topped by a cab glazed on all sides from which controllers can see aircraft on the runways and taxiways. Hong Kong International Airport is one of the busiest airports in the world, and its air traffic is managed by the Civil Aviation Department."}},
  hkasiaworld: {"k":{"zh":"展览馆","en":"Exhibition centre"},"y":"2005","d":{"zh":"亚洲国际博览馆位于机场旁，2005年启用，由多座相连的展览厅组成，屋顶是一排起伏的拱形。这里经常举办大型展览、会议和演唱会，场馆内的大型演艺厅可以容纳上万名观众。","en":"AsiaWorld-Expo stands beside the airport and opened in 2005. It is a set of linked exhibition halls under a rolling roof of vaults. It hosts large trade fairs, conferences and concerts, and its main arena can hold more than ten thousand people."}},
  hkbuddha: {"k":{"zh":"佛像","en":"Statue"},"y":"1993","h":34,"d":{"zh":"天坛大佛是一尊高34米的青铜释迦牟尼坐像，1993年落成，坐落在大屿山昂坪木鱼峰上。佛像下的三层基座仿照北京天坛的圆丘设计，因而得名。游人要登上268级石阶才能到达佛像脚下。","en":"The Tian Tan Buddha is a 34-metre bronze statue of the seated Buddha, completed in 1993 on Muk Yue Peak at Ngong Ping on Lantau. Its three-level base is modelled on the altar of the Temple of Heaven in Beijing, which gives the statue its name. Visitors climb 268 steps to reach it."},"x":[{"zh":"登上佛像需走268级石阶","en":"268 steps lead up to the statue"}]},
  hkpolin: {"k":{"zh":"佛寺","en":"Buddhist monastery"},"y":"1906","d":{"zh":"宝莲禅寺位于大屿山昂坪，1906年由几位僧人创建，1924年定名宝莲寺，是香港著名的佛教寺院。寺内有大雄宝殿和万佛殿，殿宇黄瓦红柱，色彩鲜明。天坛大佛就在寺院对面的山上。","en":"Po Lin Monastery at Ngong Ping on Lantau was founded by a few monks in 1906 and named Po Lin in 1924. It is one of the best-known Buddhist monasteries in Hong Kong. Its halls, including the Main Shrine Hall and the Grand Hall of Ten Thousand Buddhas, have yellow roofs and red columns. The Tian Tan Buddha sits on the hill opposite."}},
  hknp360tc: {"k":{"zh":"缆车站","en":"Cable car station"},"y":"2006","d":{"zh":"昂坪360东涌缆车站是缆车的起点站，位于东涌港铁站附近。缆车2006年启用，全长约5.7公里，越过东涌湾和机场岛，一路爬上大屿山的山脊，到达昂坪，全程约25分钟。","en":"The Tung Chung Terminal is the lower end of the Ngong Ping 360 cable car, close to Tung Chung MTR Station. The cable car opened in 2006 and runs about 5.7 kilometres across Tung Chung Bay and the airport island and up the Lantau ridges to Ngong Ping. The ride takes about 25 minutes."},"x":[{"zh":"缆车全长约5.7公里","en":"The ropeway is about 5.7 km long"}]},
  hknp360angle: {"k":{"zh":"缆车转向站","en":"Cable car angle station"},"y":"2006","d":{"zh":"机场岛转向站是昂坪360缆车在机场岛上的一个转向站，缆车从东涌出发越过东涌湾后在这里转弯，再向大屿山的山上进发。乘客不在这里上下车，但可以从车厢里看到机场跑道上起降的飞机。","en":"The Airport Island Angle Station is where the Ngong Ping 360 cable car turns after crossing Tung Chung Bay from Tung Chung, before heading up into the Lantau hills. Passengers do not get on or off here, but from the cabins they can watch planes on the airport runways."}},
  hknp360ng: {"k":{"zh":"缆车站","en":"Cable car station"},"y":"2006","d":{"zh":"昂坪缆车站是昂坪360缆车的终点站，就在昂坪市集的入口。下车后沿着市集走几分钟，便可到达宝莲禅寺和天坛大佛。从车站可以望见山上的大佛，周围是大屿山的群山。","en":"Ngong Ping Terminal is the upper end of the Ngong Ping 360 cable car, at the entrance of Ngong Ping Village. A short walk through the village leads to Po Lin Monastery and the Tian Tan Buddha. The Buddha can be seen on the hill from the station, surrounded by the mountains of Lantau."}},
  hkdisney: {"k":{"zh":"主题公园","en":"Theme park"},"y":"2005","d":{"zh":"香港迪士尼乐园位于大屿山东北部的竹篙湾，2005年开幕，由香港特区政府与华特迪士尼公司合资兴建。园区建在填海土地上，有多个主题区、湖泊和园林，另有度假酒店，港铁迪士尼线直达。","en":"Hong Kong Disneyland is at Penny’s Bay in north-east Lantau and opened in 2005, built as a joint venture of the Hong Kong government and The Walt Disney Company. The park lies on reclaimed land with several themed areas, lakes and gardens, plus resort hotels, and is served directly by the MTR Disneyland Resort Line."}},

  /* shenzhen */
  hkpingan: {"k":{"zh":"摩天大楼","en":"Skyscraper"},"y":"2017","a":{"zh":"KPF建筑师事务所","en":"Kohn Pedersen Fox"},"h":599.1,"fl":115,"d":{"zh":"平安金融中心位于深圳福田，是深圳最高的建筑，在中国仅次于上海中心大厦。塔身逐渐收窄，四角有不锈钢竖肋一直延伸到尖顶，外墙是石材和玻璃。天气晴朗时，从香港新界北部也能看到它。","en":"Ping An Finance Center in Futian is the tallest building in Shenzhen and second in China only to the Shanghai Tower. The tower tapers as it rises, with stainless steel ribs at its corners running up to the spire, over walls of stone and glass. On clear days it can be seen from the northern New Territories of Hong Kong."}},
  hkcrtower: {"k":{"zh":"摩天大楼","en":"Skyscraper"},"y":"2018","a":{"zh":"KPF建筑师事务所","en":"Kohn Pedersen Fox"},"h":392.5,"d":{"zh":"华润大厦位于深圳湾畔的后海，造型像一根破土而出的春笋，因此常被称为“春笋”。外墙由56根细长的竖肋组成，向上逐渐汇聚成尖顶，结构本身就是它的外观。从香港的元朗和天水围可以隔着深圳湾看到它。","en":"China Resources Tower stands at Houhai by Shenzhen Bay. Its shape recalls a bamboo shoot breaking out of the ground, so it is often called the Spring Bamboo. Its outer wall is a set of 56 slender ribs that gather into a point at the top, the structure forming the look. It can be seen across the bay from Yuen Long and Tin Shui Wai."}},
  hkkingkey: {"k":{"zh":"摩天大楼","en":"Skyscraper"},"y":"2011","a":{"zh":"泰瑞·法瑞尔事务所","en":"TFP Farrells"},"h":441.8,"fl":100,"d":{"zh":"京基100位于深圳罗湖，2011年落成时是深圳最高的建筑。塔身轮廓微微鼓起，两侧呈柔和的弧线，顶部是一个弧形的玻璃顶冠，楼上部是酒店。它靠近深圳河，从香港上水一带就能望见。","en":"KK100 in Luohu was the tallest building in Shenzhen when it was finished in 2011. The tower bulges softly with gently curved sides and ends in a curved glass crown, with a hotel on its upper floors. It stands close to the Shenzhen River and can be seen from Sheung Shui in Hong Kong."}},
  hkszbaybridge: {"k":{"zh":"跨海大桥","en":"Sea bridge"},"y":"2007","d":{"zh":"深圳湾公路大桥横跨深圳湾，连接香港的元朗鳌磡石与深圳蛇口，2007年7月通车。大桥北端是深圳湾口岸，香港与内地的出入境设施设在同一座大楼里。桥的通航段是斜拉桥，以倾斜的独柱桥塔拉起桥面。","en":"Shenzhen Bay Bridge crosses Deep Bay from Ngau Hom Shek in Yuen Long to Shekou in Shenzhen and opened in July 2007. At the northern end is the Shenzhen Bay Port, where Hong Kong and Mainland border controls share one building. The navigation spans are cable-stayed, hung from leaning single towers."}},

  /* sites (same text as the target; used if the target is built as a SITE) */
  "site:hkcentralfront": {"k":{"zh":"海滨长廊","en":"Waterfront promenade"},"d":{"zh":"中环海滨长廊是建在中环填海土地上的一段开放海滨，有草坪、步道和休憩空间，西接中环码头，东面通往添马公园和湾仔。这里经常举办嘉年华、音乐会等户外活动，也是看维港夜景的好地方。","en":"The Central Harbourfront is an open waterfront on reclaimed land, with lawns, walkways and places to sit. It runs from the Central Ferry Piers east towards Tamar Park and Wan Chai. Fairs, concerts and other outdoor events are often held here, and it is a good place to watch the harbour at night."}},
  "site:hktamar": {"k":{"zh":"公园","en":"Park"},"y":"2011","d":{"zh":"添马公园是政府总部前一片向海边缓缓倾斜的大草坪，市民可以在这里野餐、休息、看海。“添马”一名来自英国皇家海军基地添马舰，基地曾设在这一带的海旁。公园与中环和湾仔的海滨长廊相连。","en":"Tamar Park is a broad lawn that slopes gently from the government headquarters to the water, a place to picnic, rest and watch the harbour. The name comes from HMS Tamar, the Royal Navy base that once stood on this shore. The park links to the harbourfront walks of Central and Wan Chai."}},
  "site:hkzoo": {"k":{"zh":"动植物公园","en":"Zoological and botanical garden"},"y":"1871","d":{"zh":"香港动植物公园是香港历史最悠久的公园，建于19世纪60年代，1871年全面落成。园内有喷水池平台、大型鸟舍、哺乳动物园和温室，种着许多热带植物。它依山而建，就在礼宾府的对面。","en":"The Hong Kong Zoological and Botanical Gardens is the oldest park in Hong Kong, begun in the 1860s and completed in 1871. It has a fountain terrace, large aviaries, a mammal section and a greenhouse full of tropical plants. It sits on the hillside across the road from Government House."}},
  "site:hkhku": {"k":{"zh":"大学","en":"University"},"y":"1911","d":{"zh":"香港大学是香港历史最悠久的大学，1911年创立，校园沿薄扶林道的山坡层层分布。红砖与花岗岩建成的本部大楼有钟楼和爱奥尼柱廊，是校园的象征；山坡上方是2012年启用的百周年校园。孙中山曾在其前身香港西医书院求学。","en":"The University of Hong Kong, founded in 1911, is the oldest university in Hong Kong, spread over terraces on the hillside along Pok Fu Lam Road. Its red-brick and granite Main Building with a clock tower is the symbol of the campus, and the Centennial Campus opened above it in 2012. Sun Yat-sen studied at the medical college that came before it."}},
  "site:hkoceanpark": {"k":{"zh":"主题公园","en":"Theme park"},"y":"1977","d":{"zh":"海洋公园1977年开幕，建在港岛南区南朗山的两边：一边是海滨区，另一边是山上的高峰区，两区之间靠架空缆车和地下列车相连。坐缆车可以俯瞰南面开阔的海景，园内还有海洋生物展馆和机动游戏。","en":"Ocean Park opened in 1977 on both sides of a headland on the south side of Hong Kong Island. The Waterfront area and the Summit area are linked by a cable car and an underground train. The cable car gives wide views of the sea, and the park has marine animal exhibits and rides."}},
  "site:hkhappyvalley": {"k":{"zh":"赛马场","en":"Racecourse"},"y":"1846","d":{"zh":"跑马地马场坐落在港岛四面环山的谷地里，自1846年起举办赛马，是香港最早的马场。看台沿着跑道排开，周围高楼林立，夜赛时灯火通明。跑道中间的草地平日用作公众运动场。","en":"Happy Valley Racecourse sits in a valley surrounded by hills and towers on Hong Kong Island. Horse races have been held here since 1846, making it the oldest racecourse in Hong Kong. Night races are run under bright floodlights, and the infield is used as public sports pitches."},"x":[{"zh":"常在星期三晚上举行夜赛","en":"Night races are usually held on Wednesdays"}]},
  "site:hkstadium": {"k":{"zh":"体育场","en":"Stadium"},"y":"1994","d":{"zh":"香港大球场位于扫杆埔，1994年重建落成，可容纳约四万名观众。两边看台上方各有一道白色的拱形钢结构支撑顶棚。多年来这里是香港国际七人橄榄球赛的主场，直到赛事于2025年移师启德。","en":"Hong Kong Stadium in So Kon Po was rebuilt in 1994 and holds about 40,000 people. White steel arches carry the roofs over its two long stands. For many years it was the home of the Hong Kong Sevens rugby tournament, until the event moved to Kai Tak in 2025."}},
  "site:hkvicpark": {"k":{"zh":"公园","en":"Park"},"y":"1957","d":{"zh":"维多利亚公园位于铜锣湾，1957年开放，建在填平的避风塘上，是港岛最大的公园之一。园内有维多利亚女王铜像、网球场和游泳池。每逢农历新年的年宵花市和中秋节的灯会都在这里举行。","en":"Victoria Park in Causeway Bay opened in 1957 on a filled-in typhoon shelter and is one of the largest parks on Hong Kong Island. It has a statue of Queen Victoria, tennis courts and a swimming pool. The Lunar New Year flower fair and the Mid-Autumn lantern show are held here each year."}},
  "site:hkavenuestars": {"k":{"zh":"海滨长廊","en":"Waterfront promenade"},"y":"2004","d":{"zh":"星光大道是尖沙咀东部的海滨长廊，2004年开放，用以表扬香港电影人，沿途有明星手印和李小龙铜像。2019年重新设计开放，加建了波浪形的遮荫顶篷。这里是隔海欣赏港岛天际线的经典位置。","en":"The Avenue of Stars is a waterfront promenade in Tsim Sha Tsui East, opened in 2004 to honour Hong Kong’s film industry, with stars’ handprints and a statue of Bruce Lee. It reopened in 2019 with a new design and wavy shade canopies. It is the classic place to view the Hong Kong Island skyline across the water."}},
  "site:hkwalledcity": {"k":{"zh":"公园","en":"Park"},"y":"1995","d":{"zh":"九龙寨城公园建在已拆卸的九龙寨城原址上，1995年开放，采用江南园林的风格。寨城曾是世界上人口最稠密的地方之一，拆卸时保留了清代衙门建筑和南门遗迹，如今在园中展示寨城的历史。","en":"Kowloon Walled City Park was built on the site of the demolished Walled City and opened in 1995, in the style of a Jiangnan garden. The Walled City was once one of the most densely populated places on earth. Its Qing dynasty yamen building and the remains of the South Gate were kept and now tell its story."}},
  "site:hknanlian": {"k":{"zh":"园林","en":"Garden"},"y":"2006","d":{"zh":"南莲园池位于志莲净苑对面，2006年开放，由志莲净苑管理，按唐代园林风格建造。园中最引人注目的是一座金色的圆满阁，立在红色木桥旁的池水中央。园内还有奇石、松树和水车屋。","en":"Nan Lian Garden lies across the road from Chi Lin Nunnery, which looks after it. It opened in 2006 and follows the style of Tang dynasty gardens. Its most striking sight is the golden Pavilion of Absolute Perfection standing in a pond beside a red wooden bridge. The garden also has rocks, pines and a water mill."}},
  "site:hkpolyu": {"k":{"zh":"大学","en":"University"},"y":"1937","d":{"zh":"香港理工大学的前身是1937年成立的官立高级工业学院，1994年升格为大学。校园位于红磡，一栋栋红砖教学楼由平台和天桥紧密相连。东北角是扎哈·哈迪德设计的赛马会创新楼，流线形的外观和红砖校舍形成鲜明对比。","en":"The Hong Kong Polytechnic University grew from a government trade school founded in 1937 and became a university in 1994. Its campus in Hung Hom is a dense group of red-brick blocks linked by podiums and bridges. At its north-east corner the flowing Jockey Club Innovation Tower by Zaha Hadid stands out against the brick."}},
  "site:hkust": {"k":{"zh":"大学","en":"University"},"y":"1991","d":{"zh":"香港科技大学1991年创校，位于西贡清水湾的山坡上，校园从山顶一级级伸向海边，可以俯瞰牛尾海。大楼正门前有一座红色的日晷雕塑，学生称它为“红鸟”。它以科学、工程和商科闻名。","en":"The Hong Kong University of Science and Technology opened in 1991 on a hillside at Clear Water Bay, its campus stepping down from the hilltop to the sea. A red sundial sculpture, nicknamed the Red Bird by students, stands in front of the main entrance. The university is known for science, engineering and business."}},
  "site:hkcuhk": {"k":{"zh":"大学","en":"University"},"y":"1963","d":{"zh":"香港中文大学1963年成立，校园在沙田马料水的山坡上，面向吐露港，是香港面积最大的大学校园。它实行书院制，各书院分布在不同的山头。校园中心是大学广场和未圆湖一带。","en":"The Chinese University of Hong Kong was founded in 1963. Its campus at Ma Liu Shui in Sha Tin climbs a hillside above Tolo Harbour and is the largest university campus in Hong Kong. It has a college system, with colleges spread over different hilltops. The University Mall is at the heart of the campus."},"x":[{"zh":"设有九所书院","en":"Has nine colleges"}]},
  "site:hkkaitakstadium": {"k":{"zh":"体育场","en":"Stadium"},"y":"2025","a":{"zh":"Populous","en":"Populous"},"d":{"zh":"启德主场馆是启德体育园的核心，2025年3月开幕，可容纳五万名观众，是香港最大的体育场。它设有可开合的屋顶，草地可以更换，既能举办足球和橄榄球比赛，也能举办大型演唱会。","en":"Kai Tak Stadium is the centre of the Kai Tak Sports Park and opened in March 2025. It holds 50,000 people, making it the largest stadium in Hong Kong. It has a retractable roof and a pitch that can be changed, so it hosts football and rugby as well as big concerts."},"x":[{"zh":"体育园内还有室内体育馆和公众运动场","en":"The park also has an indoor arena and a public sports ground"}]},
  "site:hkwongtaisin": {"k":{"zh":"道教庙宇","en":"Taoist temple"},"y":"1921","d":{"zh":"黄大仙祠由啬色园管理，1921年在现址建成，主要供奉黄大仙，同时融合儒、释、道三教。红柱金瓦的大殿背靠狮子山，园内有九龙壁和园林。这里以求签灵验著称，农历新年时上头炷香的人潮络绎不绝。","en":"Wong Tai Sin Temple, run by Sik Sik Yuen, was built on this site in 1921 for the deity Wong Tai Sin and brings together Taoism, Buddhism and Confucianism. Its red columns and golden roofs stand with Lion Rock behind. It is famous for fortune sticks, and crowds come to offer the first incense of the Lunar New Year."}},
  "site:hkchilin": {"k":{"zh":"佛寺","en":"Buddhist nunnery"},"y":"1998","d":{"zh":"志莲净苑创建于1934年，1998年按唐代建筑风格重建。殿堂全部以木构件榫卯相接，不用一根铁钉，灰瓦屋顶舒展，围绕着莲花池错落排列。它是香港唯一一组这种风格的仿唐木构建筑群。","en":"Chi Lin Nunnery was founded in 1934 and rebuilt in 1998 in the style of the Tang dynasty. Its halls are made of timber pieces joined without a single nail, with wide grey-tiled roofs set around lotus ponds. It is the only complex in this style in Hong Kong."},"x":[{"zh":"共有16座殿堂","en":"Has 16 halls"}]},
  "site:hktaikwun": {"k":{"zh":"古迹活化项目","en":"Heritage centre"},"y":"2018","a":{"zh":"赫尔佐格和德梅隆（新建部分）","en":"Herzog & de Meuron (new buildings)"},"d":{"zh":"大馆由前中区警署、前中央裁判司署和域多利监狱三组法定古迹组成，共有16座历史建筑围绕着检阅广场。经香港赛马会活化后于2018年开放，新增了两座铝质外墙的现代建筑，用作美术馆和表演场地。","en":"Tai Kwun brings together three declared monuments: the former Central Police Station, the Central Magistracy and Victoria Prison, with 16 historic buildings around a parade ground. Revitalised by the Hong Kong Jockey Club, it opened in 2018 with two new aluminium-clad buildings for art and performances."},"x":[{"zh":"历史建筑建于19世纪中至1919年","en":"Historic blocks date from the mid-1800s to 1919"}]},
  "site:hkpolin": {"k":{"zh":"佛寺","en":"Buddhist monastery"},"y":"1906","d":{"zh":"宝莲禅寺位于大屿山昂坪，1906年由几位僧人创建，1924年定名宝莲寺，是香港著名的佛教寺院。寺内有大雄宝殿和万佛殿，殿宇黄瓦红柱，色彩鲜明。天坛大佛就在寺院对面的山上。","en":"Po Lin Monastery at Ngong Ping on Lantau was founded by a few monks in 1906 and named Po Lin in 1924. It is one of the best-known Buddhist monasteries in Hong Kong. Its halls, including the Main Shrine Hall and the Grand Hall of Ten Thousand Buddhas, have yellow roofs and red columns. The Tian Tan Buddha sits on the hill opposite."}},
  "site:hkt1": {"k":{"zh":"航站楼","en":"Airport terminal"},"y":"1998","a":{"zh":"福斯特建筑事务所","en":"Foster + Partners"},"d":{"zh":"香港国际机场一号客运大楼1998年启用，建在大屿山以北填海而成的赤鱲角上，取代了市区的旧启德机场。大楼呈Y形，屋顶由一排排轻盈的钢拱组成，自然光从拱间洒入。它曾是世界上最大的室内空间之一。","en":"Terminal 1 of Hong Kong International Airport opened in 1998 on Chek Lap Kok, an island enlarged by reclamation north of Lantau, replacing the old Kai Tak airport in the city. The Y-shaped building is covered by rows of light steel vaults that let daylight in between them. It was once one of the largest enclosed spaces in the world."}},
  "site:hkdisney": {"k":{"zh":"主题公园","en":"Theme park"},"y":"2005","d":{"zh":"香港迪士尼乐园位于大屿山东北部的竹篙湾，2005年开幕，由香港特区政府与华特迪士尼公司合资兴建。园区建在填海土地上，有多个主题区、湖泊和园林，另有度假酒店，港铁迪士尼线直达。","en":"Hong Kong Disneyland is at Penny’s Bay in north-east Lantau and opened in 2005, built as a joint venture of the Hong Kong government and The Walt Disney Company. The park lies on reclaimed land with several themed areas, lakes and gardens, plus resort hotels, and is served directly by the MTR Disneyland Resort Line."}},

  /* site building labels */
  "site:hkhku:Main Building": {"k":{"zh":"大学建筑","en":"University building"},"y":"1912","a":{"zh":"李柯伦治","en":"Leigh & Orange"},"d":{"zh":"香港大学本部大楼是港大最古老的建筑，1912年启用，红砖墙配花岗岩柱廊，中央立着钟楼，四角有塔楼。它是港大的象征，也是法定古迹。大楼围合着两个内庭院，至今仍用作教学和办公。","en":"The Main Building is the oldest building of the University of Hong Kong, opened in 1912. Red brick walls with granite colonnades surround a central clock tower, with towers at the corners. It is the symbol of the university and a declared monument, still used for teaching and offices around two inner courtyards."}},
  "site:hkpolyu:Jockey Club Innovation Tower": {"k":{"zh":"大学建筑","en":"University building"},"a":{"zh":"扎哈·哈迪德","en":"Zaha Hadid"},"d":{"zh":"赛马会创新楼是理大设计学院所在的大楼，由扎哈·哈迪德设计。大楼由一层层流线形的铝板和玻璃带构成，没有传统的楼层分隔感，与周围方正的红砖校舍形成强烈对比，是校园最醒目的建筑。","en":"The Jockey Club Innovation Tower, designed by Zaha Hadid, houses PolyU’s School of Design. It is shaped by flowing bands of aluminium and glass that blur the usual floor lines. It contrasts strongly with the square red-brick buildings around it and is the most striking building on the campus."}},
  "site:hkust:Academic Building": {"k":{"zh":"大学建筑","en":"University building"},"y":"1991","d":{"zh":"学术楼是科大的主楼，各学院的课室、实验室和办公室都连在这座大楼里。正门的大堂“中庭”是校园的交汇点，门前广场上立着红色的日晷雕塑。从大楼面海的一侧可以俯瞰牛尾海。","en":"The Academic Building is the main building of HKUST, joining classrooms, laboratories and offices of the schools under one roof. Its entrance hall, the Atrium, is the meeting point of the campus, and the red sundial sculpture stands on the piazza in front. Its sea side looks over Port Shelter."}},
});
